  "code": "\n(function(){\n  /* Adapted for this site: the section exists as a desktop and a mobile copy, and the page framework can\n     re-render a copy after hydration (which throws away anything a script added). So every .guar-section\n     is initialised on its own, a marker records that, and a MutationObserver re-initialises copies whose\n     DOM was replaced. */\n  var observerSupported = 'IntersectionObserver' in window;\n\n  function initSection(root){\n    if(!root || root.getAttribute('data-guar-init')) return;\n    root.setAttribute('data-guar-init', '1');\n\n    /* scroll-reveal orchestration */\n    var els = root.querySelectorAll('.guar-reveal');\n    if(!observerSupported){\n      Array.prototype.forEach.call(els, function(el){ el.classList.add('guar-in'); });\n    } else {\n      var io = new IntersectionObserver(function(entries){\n        entries.forEach(function(en){\n          if(en.isIntersecting){ en.target.classList.add('guar-in'); io.unobserve(en.target); }\n        });\n      }, {threshold:.18, rootMargin:'0px 0px -8% 0px'});\n      Array.prototype.forEach.call(els, function(el){ io.observe(el); });\n    }\n\n    /* headline auto-fit: if a line would overflow its column, shrink the size instead of wrapping */\n    var title = root.querySelector('.guar-title');\n    function guarFit(){\n      if(!title || !title.isConnected) return;\n      title.style.fontSize = '';\n      var fs = parseFloat(window.getComputedStyle(title).fontSize), guard = 0;\n      while(title.scrollWidth > title.clientWidth + 1 && fs > 16 && guard++ < 48){\n        fs -= 1;\n        title.style.fontSize = fs + 'px';\n      }\n    }\n    guarFit();\n    var guarRT;\n    window.addEventListener('resize', function(){ clearTimeout(guarRT); guarRT = setTimeout(guarFit, 120); });\n    if(document.fonts && document.fonts.ready){ document.fonts.ready.then(guarFit); }\n\n    /* scatter the night-sky stars */\n    var sky = root.querySelector('.guar-stars');\n    if(sky && !sky.childElementCount){\n      for(var i=0;i<16;i++){\n        var s = document.createElement('span');\n        s.className = 'guar-star';\n        s.style.left = (Math.random()*100).toFixed(2)+'%';\n        s.style.top  = (Math.random()*68).toFixed(2)+'%';\n        var sz = (1.4+Math.random()*1.8).toFixed(1);\n        s.style.width = sz+'px'; s.style.height = sz+'px';\n        s.style.animationDuration = (2.4+Math.random()*3).toFixed(2)+'s';\n        s.style.animationDelay = (Math.random()*4).toFixed(2)+'s';\n        sky.appendChild(s);\n      }\n    }\n  }\n\n  function initAll(){ Array.prototype.forEach.call(document.querySelectorAll('.guar-section'), initSection); }\n  initAll();\n  if('MutationObserver' in window){\n    var pending = null;\n    new MutationObserver(function(){\n      if(pending) return;\n      pending = setTimeout(function(){ pending = null; if(document.querySelector('.guar-section:not([data-guar-init])')) initAll(); }, 50);\n    }).observe(document.body, {childList:true, subtree:true});\n  }\n})();\n"
